import Foundation

/// Where a patch's sound actually comes from. Shown to the user on every patch
/// so it is always clear what is real sample playback vs. an approximation.
public enum PatchSourceType: String, Codable, CaseIterable, Sendable {
    /// A preset inside an SF2/DLS SoundFont bank.
    case soundFont
    /// Generated by an oscillator/synth engine (not used in Milestone 1).
    case synthesized
    /// A licensed third-party sample pack.
    case licensedSample
    /// Samples the user recorded or imported themselves.
    case userSample
    /// Built from an AI-separated stem. Always labelled experimental.
    case experimentalExtraction

    public var displayName: String {
        switch self {
        case .soundFont: return "SoundFont"
        case .synthesized: return "Synthesized"
        case .licensedSample: return "Licensed sample"
        case .userSample: return "User sample"
        case .experimentalExtraction: return "Experimental extraction"
        }
    }
}

public enum InstrumentFamily: String, Codable, CaseIterable, Sendable {
    case piano, electricPiano, organ, strings, synthStrings, pad, bell, mallet
    case flute, reed, brass, guitar, pluck, synthLead, bass, choir, ethnic, percussion, other

    public var displayName: String {
        switch self {
        case .piano: return "Piano"
        case .electricPiano: return "Electric piano"
        case .organ: return "Organ"
        case .strings: return "Strings"
        case .synthStrings: return "Synth strings"
        case .pad: return "Pad"
        case .bell: return "Bell"
        case .mallet: return "Mallet"
        case .flute: return "Flute"
        case .reed: return "Reed"
        case .brass: return "Brass"
        case .guitar: return "Guitar"
        case .pluck: return "Pluck"
        case .synthLead: return "Synth lead"
        case .bass: return "Bass"
        case .choir: return "Choir"
        case .ethnic: return "Ethnic"
        case .percussion: return "Percussion"
        case .other: return "Other"
        }
    }
}

/// Points at one preset inside a SoundFont/DLS bank file stored in the app's sound library.
public struct SoundFontReference: Codable, Hashable, Sendable {
    /// File name inside the app's SoundFonts directory (not an absolute path,
    /// so backups restore correctly on another device).
    public var fileName: String
    /// General MIDI program number 0...127.
    public var program: UInt8
    /// 0x79 is Apple's default melodic bank MSB; 0x78 is percussion.
    public var bankMSB: UInt8
    public var bankLSB: UInt8

    public static let melodicBankMSB: UInt8 = 0x79
    public static let percussionBankMSB: UInt8 = 0x78

    public init(fileName: String, program: UInt8, bankMSB: UInt8 = SoundFontReference.melodicBankMSB, bankLSB: UInt8 = 0) {
        self.fileName = fileName
        self.program = program
        self.bankMSB = bankMSB
        self.bankLSB = bankLSB
    }
}

/// Reference to a single audio sample file for user/licensed sample patches (Milestone 3+).
public struct SampleZone: Codable, Hashable, Sendable {
    public var fileName: String
    public var rootNote: MIDINote
    public var keyRange: KeyRange
    public var velocityRange: VelocityRange
    public var startFrame: Int
    public var endFrame: Int?
    public var loopStart: Int?
    public var loopEnd: Int?

    public init(fileName: String, rootNote: MIDINote, keyRange: KeyRange, velocityRange: VelocityRange = .full,
                startFrame: Int = 0, endFrame: Int? = nil, loopStart: Int? = nil, loopEnd: Int? = nil) {
        self.fileName = fileName
        self.rootNote = rootNote
        self.keyRange = keyRange
        self.velocityRange = velocityRange
        self.startFrame = startFrame
        self.endFrame = endFrame
        self.loopStart = loopStart
        self.loopEnd = loopEnd
    }
}

public struct Envelope: Codable, Hashable, Sendable {
    /// Seconds.
    public var attack: Double
    public var decay: Double
    /// 0...1 level.
    public var sustain: Double
    public var release: Double

    public init(attack: Double = 0.005, decay: Double = 0.2, sustain: Double = 1.0, release: Double = 0.3) {
        self.attack = attack
        self.decay = decay
        self.sustain = sustain
        self.release = release
    }
}

public struct FilterSettings: Codable, Hashable, Sendable {
    public var enabled: Bool
    /// Hz.
    public var cutoff: Double
    /// dB.
    public var resonance: Double

    public init(enabled: Bool = false, cutoff: Double = 20_000, resonance: Double = 0) {
        self.enabled = enabled
        self.cutoff = cutoff
        self.resonance = resonance
    }
}

public struct EffectSettings: Codable, Hashable, Sendable {
    /// 0...100 wet/dry percentage.
    public var reverbMix: Double
    public var delayMix: Double
    /// Seconds.
    public var delayTime: Double
    public var delayFeedback: Double

    public init(reverbMix: Double = 15, delayMix: Double = 0, delayTime: Double = 0.35, delayFeedback: Double = 25) {
        self.reverbMix = reverbMix
        self.delayMix = delayMix
        self.delayTime = delayTime
        self.delayFeedback = delayFeedback
    }
}

public struct LicenseInfo: Codable, Hashable, Sendable {
    public var name: String
    public var url: String?
    public var redistributable: Bool
    public var notes: String?

    public init(name: String, url: String? = nil, redistributable: Bool, notes: String? = nil) {
        self.name = name
        self.url = url
        self.redistributable = redistributable
        self.notes = notes
    }

    public static let unknown = LicenseInfo(name: "Unknown — user supplied", redistributable: false,
                                            notes: "Do not share this patch's audio without checking the source license.")
}

/// One playable instrument sound. Layers reference patches by id.
public struct InstrumentPatch: Codable, Hashable, Identifiable, Sendable {
    public var id: UUID
    public var name: String
    public var family: InstrumentFamily
    public var sourceType: PatchSourceType
    public var soundFont: SoundFontReference?
    public var sampleZones: [SampleZone]
    public var envelope: Envelope
    public var filter: FilterSettings
    public var effects: EffectSettings
    public var isFavorite: Bool
    public var license: LicenseInfo
    public var notes: String?

    public init(id: UUID = UUID(), name: String, family: InstrumentFamily, sourceType: PatchSourceType,
                soundFont: SoundFontReference? = nil, sampleZones: [SampleZone] = [],
                envelope: Envelope = Envelope(), filter: FilterSettings = FilterSettings(),
                effects: EffectSettings = EffectSettings(), isFavorite: Bool = false,
                license: LicenseInfo = .unknown, notes: String? = nil) {
        self.id = id
        self.name = name
        self.family = family
        self.sourceType = sourceType
        self.soundFont = soundFont
        self.sampleZones = sampleZones
        self.envelope = envelope
        self.filter = filter
        self.effects = effects
        self.isFavorite = isFavorite
        self.license = license
        self.notes = notes
    }
}
